examples.code:
/* хорошо: только композитинг, раскладка не пересчитывается */
.card {
  transition: transform .2s ease-out, opacity .2s ease-out, box-shadow .2s ease-out;
}
.card:hover {
  transform: translateY(-4px) scale(1.01);
  box-shadow: 0 18px 40px rgba(0, 0, 0, .45);
}

/* плохо: каждый кадр пересчитывает геометрию всей страницы */
.card:hover { width: 340px; margin-top: -4px; }

/* уважение к системной настройке */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

